ALTER TABLE "care_request_applications" ADD COLUMN "proposed_start_time" time;--> statement-breakpoint
ALTER TABLE "care_requests" ADD COLUMN "requested_start_time" time;--> statement-breakpoint
ALTER TABLE "care_request_applications" ADD CONSTRAINT "care_request_applications_proposed_start_time_slot" CHECK ("care_request_applications"."proposed_start_time" IS NULL OR ("care_request_applications"."proposed_start_time" BETWEEN '18:00' AND '23:00' AND date_part('minute', "care_request_applications"."proposed_start_time") IN (0, 30) AND date_part('second', "care_request_applications"."proposed_start_time") = 0));--> statement-breakpoint
ALTER TABLE "care_requests" ADD CONSTRAINT "care_requests_requested_start_time_slot" CHECK ("care_requests"."requested_start_time" IS NULL OR ("care_requests"."requested_start_time" BETWEEN '18:00' AND '23:00' AND date_part('minute', "care_requests"."requested_start_time") IN (0, 30) AND date_part('second', "care_requests"."requested_start_time") = 0 AND "care_requests"."requested_start_time" <> "care_requests"."start_time"));